def count_flips(tiling, n):
    # tiling is a list of (r1, c1, r2, c2)
    # A flip is a 2x2 area with two parallel dominoes.
    # That means a 2x2 area {(r, c), (r, c+1), (r+1, c), (r+1, c+1)} 
    # is covered by either:
    # 1. {(r, c), (r, c+1)} and {(r+1, c), (r+1, c+1)}
    # 2. {(r, c), (r+1, c)} and {(r, c+1), (r+1, c+1)}

    flips = 0
    # We only need to check 2x2 areas.
    # There are (n-1)x(n-1) such areas.
    for r in range(n - 1):
        for c in range(n - 1):
            # Area cells: (r, c), (r, c+1), (r+1, c), (r+1, c+1)
            cells = {(r, c), (r, c+1), (r+1, c), (r+1, c+1)}
            # Find the dominoes in this tiling that cover these cells.
            # Since it's a tiling, there are exactly 2 dominoes.
            dominoes_in_area = []
            for d in tiling:
                d_cells = {(d[0], d[1]), (d[2], d[3])}
                if d_cells.issubset(cells):
                    dominoes_in_area.append(d_cells)

            if len(dominoes_in_area) == 2:
                # Check if they are parallel
                d1 = dominoes_in_area[0]
                d2 = dominoes_in_area[1]

                # Are they both horizontal?
                # d is horizontal if the two cells have the same row.
                is_h1 = (d1[0][0] == d1[1][0])
                is_h2 = (d2[0][0] == d2[1][0])

                if is_h1 and is_h2:
                    flips += 1
                    continue

                # Are they both vertical?
                is_v1 = (d1[0][1] == d1[1][1])
                is_v2 = (d2[0][1] == d2[1][1])

                if is_v1 and is_v2:
                    flips += 1
                    continue
    return flips

def generate_tilings(n):
    # Simple recursive generation
    def solve(board):
        if all(cell in board for cell in [(r, c) for r in range(n) for c in range(n)]):
            return [[]]

        # Find first empty cell
        r, c = -1, -1
        for i in range(n):
            for j in range(n):
                if (i, j) not in board:
                    r, c = i, j
                    break
            if r != -1: break

        res = []
        # Try horizontal
        if c + 1 < n and (r, c+1) not in board:
            board.add((r, c))
            board.add((r, c+1))
            sub_tilings = solve(board)
            for st in sub_tilings:
                res.append([(r, c, r, c+1)] + st)
            board.remove((r, c))
            board.remove((r, c+1))

        # Try vertical
        if r + 1 < n and (r+1, c) not in board:
            board.add((r, c))
            board.add((r+1, c))
            sub_tilings = solve(board)
            for st in sub_tilings:
                res.append([(r, c, r+1, c)] + st)
            board.remove((r, c))
            board.remove((r+1, c))

        return res

    board = set()
    return solve(board)

