def check_any_2x2_free_tiling_efficient(n):
    # Using a backtracking approach with better pruning
    def solve(r, c, occupied, current_tiling):
        if r == n:
            return 1

        next_r, next_c = (r, c+1) if c+1 < n else (r+1, 0)

        if (r, c) in occupied:
            return solve(next_r, next_c, occupied, current_tiling)

        count = 0
        # Try horizontal
        if c + 1 < n and (r, c+1) not in occupied:
            new_domino = ((r, c), (r, c+1))
            # Check 2x2 block: horizontal domino at (r,c) and (r,c+1)
            # is bad if there's a horizontal domino at (r-1,c) and (r-1,c+1)
            bad = False
            if r > 0:
                if ((r-1, c), (r-1, c+1)) in current_tiling:
                    bad = True

            if not bad:
                occupied.add((r, c))
                occupied.add((r, c+1))
                current_tiling.append(new_domino)
                count += solve(next_r, next_c, occupied, current_tiling)
                current_tiling.pop()
                occupied.remove((r, c))
                occupied.remove((r, c+1))

        # Try vertical
        if r + 1 < n and (r+1, c) not in occupied:
            new_domino = ((r, c), (r+1, c))
            # Check 2x2 block: vertical domino at (r,c) and (r+1,c)
            # is bad if there's a vertical domino at (r,c-1) and (r+1,c-1)
            bad = False
            if c > 0:
                if ((r, c-1), (r+1, c-1)) in current_tiling:
                    bad = True

            if not bad:
                occupied.add((r, c))
                occupied.add((r+1, c))
                current_tiling.append(new_domino)
                count += solve(next_r, next_c, occupied, current_tiling)
                current_tiling.pop()
                occupied.remove((r, c))
                occupied.remove((r+1, c))

        return count

    occupied = set()
    return solve(0, 0, occupied, [])

