def solve_tiling(n):
    tilings = []
    def get_tilings(board, current_tiling):
        r, c = -1, -1
        for i in range(n):
            for j in range(n):
                if board[i][j] == 0:
                    r, c = i, j
                    break
            if r != -1:
                break
        if r == -1:
            tilings.append(list(current_tiling))
            return
        if c + 1 < n and board[r][c+1] == 0:
            board[r][c] = 1
            board[r][c+1] = 1
            current_tiling.append(((r, c), (r, c+1)))
            get_tilings(board, current_tiling)
            current_tiling.pop()
            board[r][c] = 0
            board[r][c+1] = 0
        if r + 1 < n and board[r+1][c] == 0:
            board[r][c] = 1
            board[r+1][c] = 1
            current_tiling.append(((r, c), (r+1, c)))
            get_tilings(board, current_tiling)
            current_tiling.pop()
            board[r][c] = 0
            board[r+1][c] = 0
    board = [[0]*n for _ in range(n)]
    get_tilings(board, [])
    return tilings

def is_valid(tiling, marks):
    for d in tiling:
        m_in_d = 0
        for m in marks:
            if m == d[0] or m == d[1]:
                m_in_d += 1
        if m_in_d > 1:
            return False
    return True

