def find_tilings_with_no_flips(n):
    grid = [[None] * n for _ in range(n)]

    def is_valid(r, c):
        # Check for flips in 2x2 blocks that are now complete
        # The 2x2 block is (r-1, c-1), (r-1, c), (r, c-1), (r, c)
        if r > 0 and c > 0:
            # Check horizontal flip
            d1 = grid[r-1][c-1]
            d2 = grid[r-1][c]
            d3 = grid[r][c-1]
            d4 = grid[r][c]
            # Horizontal flip: d1 == d2 and d3 == d4 and d1 != d3
            # Actually, if d1 == d2, it means it's a horizontal domino (r-1, c-1)-(r-1, c)
            # If d3 == d4, it means it's a horizontal domino (r, c-1)-(r, c)
            # If they are different, it's a flip.
            if d1 == d2 and d3 == d4 and d1 != d3:
                return False
            # Vertical flip: d1 == d3 and d2 == d4 and d1 != d2
            if d1 == d3 and d2 == d4 and d1 != d2:
                return False
        return True

    def backtrack(r, c):
        if r == n:
            return True
        if c == n:
            return backtrack(r + 1, 0)
        if grid[r][c] is not None:
            return backtrack(r, c + 1)

        # Try horizontal
        if c + 1 < n and grid[r][c+1] is None:
            grid[r][c] = grid[r][c+1] = (r, c)
            if is_valid(r, c + 1):
                if backtrack(r, c + 1):
                    return True
            grid[r][c] = grid[r][c+1] = None

        # Try vertical
        if r + 1 < n and grid[r+1][c] is None:
            grid[r][c] = grid[r+1][c] = (r, c)
            if is_valid(r + 1, c):
                if backtrack(r, c + 1):
                    return True
            grid[r][c] = grid[r+1][c] = None

        return False

    if backtrack(0, 0):
        return True
    else:
        return False

