def solve_4x4():
    # A 4x4 board has 36 tilings.
    # We can represent a tiling as a set of 8 dominoes.
    # Each domino is a tuple of two cells.
    cells = [(r, c) for r in range(4) for c in range(4)]

    def get_tilings(remaining_cells):
        if not remaining_cells:
            yield []
            return

        r, c = min(remaining_cells)
        # Try horizontal
        if (r, c+1) in remaining_cells:
            for rest in get_tilings([cell for cell in remaining_cells if cell != (r, c) and cell != (r, c+1)]):
                yield [((r, c), (r, c+1))] + rest
        # Try vertical
        if (r+1, c) in remaining_cells:
            for rest in get_tilings([cell for cell in remaining_cells if cell != (r, c) and cell != (r+1, c)]):
                yield [((r, c), (r+1, c))] + rest

    for tiling in get_tilings(set(cells)):
        # A tiling is flip-free if no 2x2 block is two horizontal or two vertical.
        # A 2x2 block is {(r, c), (r, c+1), (r+1, c), (r+1, c+1)}
        is_flip_free = True
        for r in range(3):
            for c in range(3):
                # Check the 2x2 block at (r, c), (r, c+1), (r+1, c), (r+1, c+1)
                # Find the dominoes for these 4 cells
                dominoes = []
                for d in tiling:
                    if d[0] in [(r, c), (r, c+1), (r+1, c), (r+1, c+1)] or d[1] in [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]:
                        dominoes.append(d)

                # If these 4 cells are covered by exactly 2 dominoes, and they are both horizontal or both vertical:
                if len(dominoes) == 2:
                    d1, d2 = dominoes
                    # If d1 and d2 are both horizontal and cover the 2x2 block
                    if d1[0][0] == d1[1][0] and d2[0][0] == d2[1][0]: # Both horizontal
                        # They must be (r, c)-(r, c+1) and (r+1, c)-(r+1, c+1)
                        if (d1[0][0] == r and d1[1][0] == r) and (d2[0][0] == r+1 and d2[1][0] == r+1):
                            is_flip_free = False
                            break
                    # If d1 and d2 are both vertical and cover the 2x2 block
                    if d1[0][1] == d1[1][1] and d2[0][1] == d2[1][1]: # Both vertical
                        # They must be (r, c)-(r+1, c) and (r, c+1)-(r+1, c+1)
                        if (d1[0][1] == c and d1[1][1] == c) and (d2[0][1] == c+1 and d2[1][1] == c+1):
                            is_flip_free = False
                            break
            if not is_flip_free:
                break
        if is_flip_free:
            return tiling
    return None

