def solve_small(n):
    cells = [(r, c) for r in range(n) for c in range(n)]

    def get_tilings(cells_left):
        if not cells_left:
            yield []
            return

        # Pick the first available cell
        r, c = min(cells_left)

        # Try horizontal domino
        if (r, c+1) in cells_left and c+1 < n:
            for rest in get_tilings(cells_left - {(r,c), (r,c+1)}):
                yield [((r,c), (r,c+1))] + rest

        # Try vertical domino
        if (r+1, c) in cells_left and r+1 < n:
            for rest in get_tilings(cells_left - {(r,c), (r+1,c)}):
                yield [((r,c), (r+1,c))] + rest

    all_tilings = list(get_tilings(set(cells)))

    for k in range(1, n*n + 1):
        for marks in itertools.combinations(cells, k):
            marks_set = set(marks)
            valid_tilings = []
            for tiling in all_tilings:
                # Condition 1: No domino in tiling has > 1 mark
                if all(len(set(domino) & marks_set) <= 1 for domino in tiling):
                    valid_tilings.append(tiling)

            if len(valid_tilings) == 1:
                return k, marks_set
    return None

